import{d as r,C as s,o as d,c as h,a3 as t,E as e,j as a,a as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十七章","description":"《正易心法》第二十七章——每卦之体，六画便具：初爻为地、上爻为天、二北五南、四西三东，天地四方是为六虚；六画乃天地四方之象，非六虚即六画。","frontmatter":{"title":"正易心法·第二十七章","description":"《正易心法》第二十七章——每卦之体，六画便具：初爻为地、上爻为天、二北五南、四西三东，天地四方是为六虚；六画乃天地四方之象，非六虚即六画。","category":"guide","aliases":["正易心法第二十七章","每卦之体六画便具","六虚"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-27.md","filePath":"yijing/zheng-yi-xin-fa/chapter-27.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-27.md"},x=r({...c,setup(u){const i=[{id:"z27-01",label:"一、六画便具六虚",showLabel:!0,sentences:[["每卦之体，",{text:"六画",glossary:"liuhua"},"便具。天地四方，是为",{text:"六虚",glossary:"liuxu"},"。"]],note:["每一个卦的本体，六爻便已完整具备；天、地、东、南、西、北四方，就是六虚。（**「六虚」的「虚」是空间，不是实体**：六爻不是六个实体，而是六个空间方位的象征。**这一章把卦从「符号」变成了「坐标」**——每一卦都是一个完整的宇宙空间模型。）"]},{id:"z27-02",label:"二、六爻方位",showLabel:!0,sentences:[["初爻为地，上爻为天，二爻为北，五爻为南，四爻为西，三爻为东。天地四方，每卦之体，皆具此义，是为六虚。"]],note:["初爻对应地，上爻对应天，二爻对应北，五爻对应南，四爻对应西，三爻对应东。天地四方，每一个卦的本体都具备这个意义，这就是六虚。（**对应不是随意排的**：初在最下为地、上在最上为天（纵轴）；**中爻二、五是上下卦的「中位」，主南北**；三、四爻在下卦之顶、上卦之底，正是阴阳交界处，主东西。**天地（上下）+ 南北 + 东西 = 一个完整的三维坐标。**）"]},{id:"z27-03",label:"三、周流六虚",showLabel:!0,sentences:[["《大传》：“变动不拘，",{text:"周流六虚",glossary:"zhouliuLiuxu"},"”正谓此耳。"]],note:["《大传》（《系辞传》）说「变动不拘，周流六虚」，说的正是这个。（**两种读法**：传统理解把六虚当作「卦内的六个格子」，爻在格子里移动；麻衣的读法是「六虚＝天地四方」，爻的变动遍及整个宇宙空间。**前者封闭在符号内部，后者让卦与宇宙直接对应。** 通行本作「变动不居」，此处「不拘」随底本。）"]},{id:"z27-04",label:"四、六画之象",showLabel:!0,sentences:[["学者不悟，谓六虚天地四方，乃六画也，殊不知六画乃天地四方之象。"]],note:["学者不能领悟，以为六虚、天地四方就是六爻的画线而已——却不知道，六爻的画线正是天地四方的象征。（**这一句把「象」与「实」的关系点破了**：六画是「象」（看得见的符号），六虚是「实」（看不见的空间）。**在易学里，「虚」反而是「实」，「实」（符号）反而是「虚」（表象）。** 这与全书一贯的认识论一致：不要停留在符号层面，要穿透符号看见它所指向的真实。）"]},{id:"z27-05",label:"五、纸上工夫",showLabel:!0,sentences:[["此之谓",{text:"纸上工夫",glossary:"zhishangGongfu"},"，不知",{text:"落处",glossary:"luochu"},"也。"]],note:["这就叫做纸上工夫，不知道落处。（**这是全书第一次用「落处」来批评一种具体的错误**：把六画当成六虚，就是把地图当成了土地。**「纸上工夫」四字与第一章「玩占亦虚语」完全同调**——麻衣对「只做书面功夫」的批评，从他开篇一直贯到此处。）"]}],l=[{id:"liuhua",term:"六画",pinyin:"liù huà",meaning:"六爻卦的六条爻画。麻衣强调六画只是「象」，不是「实」。"},{id:"liuxu",term:"六虚",pinyin:"liù xū",meaning:"六个虚位。虚＝空间：六爻对应天地四方六个空间维度。"},{id:"zhouliuLiuxu",term:"周流六虚",pinyin:"zhōu liú liù xū",meaning:"《系辞传》语。麻衣读作「爻的变动遍及天地四方」，而非「在卦内六个格子里移动」。"},{id:"zhishangGongfu",term:"纸上工夫",pinyin:"zhǐ shàng gōng fu",meaning:"只在文字与符号层面下功夫。麻衣批评语：只知符号，不知实义。"},{id:"luochu",term:"落处",pinyin:"luò chù",meaning:"卦象的实际落脚之处。全书核心词，本章第一次用它来批评具体错误。"}];return(b,n)=>{const p=s("DaoTextReading"),o=s("DaoKeywordCards");return d(),h("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第二十七章" tabindex="-1">正易心法·第二十七章 <a class="header-anchor" href="#正易心法·第二十七章" aria-label="Permalink to &quot;正易心法·第二十七章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章的核心命题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六爻卦的六爻，对应天地四方六个空间维度</span></span>
<span class="line"><span>这六个维度就是「六虚」</span></span>
<span class="line"><span>每一卦都是一个完整的宇宙空间模型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>对应关系：</span></span>
<span class="line"><span>  初爻＝地，上爻＝天</span></span>
<span class="line"><span>  二爻＝北，五爻＝南</span></span>
<span class="line"><span>  三爻＝东，四爻＝西</span></span></code></pre></div><p><strong>批评</strong>：学者误以为六虚就是六画（符号）；实则<strong>六画是六虚（空间）的象</strong>——混淆象与实，就是「纸上工夫」。</p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「六虚」的「虚」字</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>虚 = 空间（非实体）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>六爻不是六个实体，而是六个空间方位的象征</span></span>
<span class="line"><span>爻画（实）→ 象征 → 方位（虚）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>「虚」强调的是：六爻是空间的容器，不是空间本身</span></span>
<span class="line"><span>= 六画是象，六虚是实</span></span></code></pre></div><p><strong>方位对应的内在逻辑</strong>：</p><table tabindex="0"><thead><tr><th>爻</th><th>方位</th><th>为什么</th></tr></thead><tbody><tr><td>初</td><td>地</td><td>在最下方</td></tr><tr><td>上</td><td>天</td><td>在最上方</td></tr><tr><td>二</td><td>北</td><td>下卦中位（阴位）——幽暗之方</td></tr><tr><td>五</td><td>南</td><td>上卦中位（阳位）——光明之方</td></tr><tr><td>三</td><td>东</td><td>下卦之顶，阳气上升之处（日出）</td></tr><tr><td>四</td><td>西</td><td>上卦之底，阴气初入之处（日落）</td></tr></tbody></table><p><strong>整体结构</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>天地（初上）= 纵轴</span></span>
<span class="line"><span>南北（二五）= 内外主轴</span></span>
<span class="line"><span>东西（三四）= 阴阳交界轴</span></span>
<span class="line"><span>= 一个完整的宇宙坐标系</span></span></code></pre></div><p><strong>「周流六虚」的两种读法</strong>：</p><table tabindex="0"><thead><tr><th></th><th>六虚</th><th>周流六虚</th></tr></thead><tbody><tr><td>传统理解</td><td>六爻的六个位置</td><td>爻在六个位置上流动（封闭在符号内部）</td></tr><tr><td>麻衣的读法</td><td>天地四方六个空间维度</td><td>爻的变动遍及整个宇宙空间（卦与宇宙直接对应）</td></tr></tbody></table><p><strong>与第一章「落处」的呼应</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第一章：「画前之易，落于何处？」——学《易》首要知道卦象的落处</span></span>
<span class="line"><span>第二十七章：六画＝天地四方之象，落处＝真实的宇宙空间</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣批评：「此之谓纸上工夫，不知落处也」</span></span>
<span class="line"><span>  错误：以为六虚就是六画（符号层面）</span></span>
<span class="line"><span>  正确：六画是六虚的象（空间层面）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  纸上工夫 = 停留在符号层面</span></span>
<span class="line"><span>  知落处   = 穿透符号，见到真实空间</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把六个对应记住：<strong>初地、上天、二北、五南、四西、三东</strong>；</li><li>再看「虚」字的分量：<strong>六画是象，六虚是实</strong>；</li><li>最后读「纸上工夫」——<strong>这是全书第一次用「落处」批评具体错误。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>六画便具</strong>：每一卦都是一具完整的空间模型。</li><li><strong>六虚</strong>：天地四方六个空间维度。</li><li><strong>方位</strong>：初地、上天、二北、五南、四西、三东。</li><li><strong>周流六虚</strong>：爻的变动遍及天地四方。</li><li><strong>六画之象</strong>：六画是天地四方的象征。</li><li><strong>纸上工夫</strong>：把地图当土地，即不知落处。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,21)),e(p,{colophon:"六画便具 · 天地四方 · 周流六虚 · 知落处",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十七章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文引《大传》作「变动不拘」，通行本作「变动不居」，此处随底本，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[g("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(o,{items:[{term:"六虚",pinyin:["liù","xū"],meaning:"六个虚位。「虚」是空间而非实体：六爻对应天地四方六个空间维度，故「虚」反而是「实」。"},{term:"六爻方位",pinyin:["liù","yáo"],meaning:"初爻为地、上爻为天、二爻为北、五爻为南、四爻为西、三爻为东——一个完整的三维坐标。"},{term:"周流六虚",pinyin:["zhōu","liú"],meaning:"《系辞》语。麻衣读作「爻的变动遍及天地四方」，而非「在卦内六个格子里移动」。"},{term:"六画之象",pinyin:["liù","huà"],meaning:"六画是「象」（看得见的符号），六虚是「实」（看不见的空间）——不可把象当实。"},{term:"纸上工夫",pinyin:["zhǐ","shàng"],meaning:"只在符号层面下功夫，即把地图当土地。与第一章「玩占亦虚语」同调。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章的核心命题：<strong>六爻卦的六爻对应天地四方六个空间维度，即「六虚」；每一卦都是一个完整的宇宙空间模型。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>初爻＝地，上爻＝天</span></span>
<span class="line"><span>二爻＝北，五爻＝南</span></span>
<span class="line"><span>三爻＝东，四爻＝西</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「虚」与「实」的辩证</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>六画（爻的线条）= 实（看得见的符号）</span></span>
<span class="line"><span>六虚（天地四方）= 虚（看不见的空间）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>但：看得见的符号 = 象（表面）</span></span>
<span class="line"><span>    看不见的空间 = 实（本质）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>= 在易学中，「虚」反而是「实」，「实」（符号）反而是「虚」（表象）</span></span></code></pre></div><p><strong>「周流六虚」的两读</strong>：</p><table tabindex="0"><thead><tr><th></th><th>六虚</th><th>周流六虚</th></tr></thead><tbody><tr><td>传统</td><td>卦内六个位置</td><td>爻在格子里移动（封闭）</td></tr><tr><td>麻衣</td><td>天地四方（空间）</td><td>爻的变动遍及宇宙（对应）</td></tr></tbody></table><p><strong>与第一章「落处」的呼应</strong>：<strong>这是全书第一次用「落处」批评具体的错误。</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>错误：以为六虚就是六画（符号层面）</span></span>
<span class="line"><span>正确：六画是六虚的象（空间层面）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>纸上工夫 = 停留在符号层面</span></span>
<span class="line"><span>知落处   = 穿透符号，见到真实</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>记住六个对应：<strong>初地、上天、二北、五南、四西、三东</strong>；</li><li>读「虚」字时要小心：<strong>在易学里，「虚」指的往往是更实的那一层</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>麻衣批评「纸上工夫」，那么「知道六虚是天地四方」算不算另一种纸上工夫？</strong> 我的看法：<strong>算，如果只是把对应表背下来。</strong> 麻衣的「知落处」不是<strong>记住一个映射表</strong>，而是<strong>在起卦时真的把六爻当空间看</strong>。<strong>判据是：你是「多了一张表」，还是「换了一双眼睛」。</strong> 这也正是第四十一章说的「活法」与「死法」之别——<strong>表是死法，眼睛是活法。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>每一个卦的本体，六爻便已完整具备；天、地、东、南、西、北四方，就是六虚。</p><p>初爻对应地，上爻对应天，二爻对应北，五爻对应南，四爻对应西，三爻对应东。天地四方，每一个卦的本体都具备这个意义，这就是六虚。</p><p>《大传》（《系辞传》）说「变动不拘，周流六虚」，说的正是这个。</p><p>学者不能领悟，以为六虚、天地四方就是六爻的画线而已——却不知道，六爻的画线正是天地四方的象征。</p><p>这就叫做纸上工夫，不知道落处。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第二十七章把卦从「一张图」变成了「一个空间」——<strong>六爻不是六个符号，是六个方位；你读的不是画，是坐标。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「六虚」的「虚」</strong>——这个字最容易被读反。<strong>「虚」不是「空无」，是「空间」。</strong> 所以这一章里，<strong>虚的那一层反而是实，实的那一层（六画）反而是象。</strong></li><li><strong>「初地、上天、二北、五南、四西、三东」</strong>——乍看零乱，理清就顺了：<strong>纵轴是天地（初上），主轴是南北（二五，两个中位），交界轴是东西（三四，上下卦的交界）。</strong></li><li><strong>「周流六虚」</strong>——通行本的读法是「爻在卦内六个位置上流动」，麻衣的读法是「<strong>爻的变动遍及天地四方</strong>」。<strong>前者是符号游戏，后者是宇宙对应。</strong> 一字不改，境界全变。</li><li><strong>「六画乃天地四方之象」</strong>——这句把象与实的关系点破了。<strong>画是象，方是实。</strong> 我平时读卦，很容易停在画上。</li><li><strong>「纸上工夫」</strong>——这是全书第一次用「落处」批评具体的错误：<strong>把地图当土地。</strong> 这四个字用在今天也不过时：<strong>我在做的是「真的在地方」，还是「在地图上画圈」？</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>知道「六虚是天地四方」，算不算又一层纸上工夫？</strong> 我的看法：<strong>算，如果只是背下对应表。</strong> 麻衣要的不是「多一张表」，是「换一双眼睛」。<strong>判据很简单：你现在看六爻，看到的是六个记号，还是六个位置？</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「落处」（本章第一次以「纸上工夫」批评其反面）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-14">第十四章 · 人之坎离</a> — 体用之辨（同样讲「不可执象忘实」）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-24">第二十四章 · 见于日用</a> — 「《易》在日用」（本章的「落处」是天地四方）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「变动不居，周流六虚」：麻衣读「不居」处为「不拘」</li></ul>`,25))])}}});export{y as __pageData,x as default};
